  "culture": [
    {
      "title": "सम्पदा · A landscape of memory",
      "text": "Sampada means heritage. In Sinja and Dailekh, inscriptions, monuments and oral traditions connect today’s communities to the Khasa past. A local guide can explain the evidence while making space for the stories people share.",
      "source": "https://whc.unesco.org/en/tentativelists/5263"
    },
    {
      "title": "देउडा · Listen, then join",
      "text": "Deuda is part of Karnali’s musical and social life. Seek a locally arranged gathering, ask whether participation is welcome and pay performers fairly. A living tradition deserves more than a hurried photograph.",
      "source": "https://trade.ntb.gov.np/karnali-tourism-meet-2026/"
    },
    {
      "title": "अतिथि · Travel as a guest",
      "text": "Atithi means guest. In Dolpo and Humla, homes and monasteries belong to living communities with distinct traditions. Ask about local customs, request permission for photographs and follow your hosts’ guidance around sacred spaces.",
      "source": "https://whc.unesco.org/document/1098"
    }
  ],
